package io.github.rebrowser.review;
import static org.junit.Assert.*;
import io.github.rebrowser.music.*;
import io.github.rebrowser.lyrics.*;
import io.github.rebrowser.outlook.MailSearch;
import java.io.*;
import java.util.*;
import java.util.concurrent.atomic.AtomicBoolean;
import org.junit.Test;
/** Main-authored adversarial production models/algorithms. No realOS/Gecko/account/keys/files. */
public final class D03MainPureRegressionTest {
 private static MusicState playing(){return new MusicState(MusicState.Account.UNKNOWN,MusicState.Playback.PLAYING,MusicState.Focus.NONE,"t","a",null,10,10000,1,100);}
 @Test public void clockRollbackCannotReplaceObservation(){MusicState s=playing();assertThrows(IllegalArgumentException.class,()->s.observe(MusicState.Playback.PAUSED,10,10000,99));}
 @Test public void playingDoesNotSupplyAnUnobservedRate(){assertFalse(playing().estimatePosition(1,200).known());}
 @Test public void nativeRateAndSourceIdentityAreSeparate(){MusicState s=playing(),other=playing();MusicState.Estimate e=s.estimatePosition(1,200,2d);assertEquals(210,e.positionMs());assertTrue(e.belongsTo(s));assertFalse(e.belongsTo(other));}
 @Test public void rateBoundsAndTimeLimitsRejectBadEstimates(){MusicState s=playing();assertThrows(IllegalArgumentException.class,()->s.estimatePosition(1,200,Double.NaN));assertThrows(IllegalArgumentException.class,()->s.estimatePosition(1,200,Double.POSITIVE_INFINITY));assertThrows(IllegalArgumentException.class,()->s.estimatePosition(1,200,17d));assertTrue(s.estimatePosition(1,Long.MAX_VALUE,1d).stale());}
 @Test public void unknownQueueIsNotAnEmptyOfficialQueue(){assertEquals(MusicQueue.ViewState.UNREAD,MusicQueue.unread().windowAll("").state());assertEquals(MusicQueue.ViewState.EMPTY,MusicQueue.empty().state());}
 @Test public void explicitSubsetTruncationSurvivesEmptyWindow(){MusicQueue q=new MusicQueue(Collections.emptyList(),1,"native subset",true);assertEquals(MusicQueue.ViewState.TRUNCATED,q.window(0,1,"").state());assertTrue(q.window(0,1,"").hasMore());}
 @Test public void queueFilterBoundAppliesBeforeWhitespaceNormalization(){MusicQueue q=MusicQueue.empty();assertThrows(IllegalArgumentException.class,()->q.window(0,1,new String(new char[100000]).replace('\0',' ')));assertThrows(IllegalArgumentException.class,()->q.window(0,1,"\ud800"));}
 @Test public void queueTrackDoesNotInventOfferedActions(){MusicQueue.Track t=new MusicQueue.Track("t","t","a","",1,MusicQueue.Like.UNKNOWN);for(MusicQueue.Action a:MusicQueue.Action.values())assertFalse(t.offers(a));}
 @Test public void boundedPreferenceShapeIsNotAnUnboundedStoredSchema(){Map<String,String> map=new HashMap<>();for(int i=0;i<17;i++)map.put("k"+i,"v");assertThrows(IllegalArgumentException.class,()->MusicPreferences.rejectedFields(map));assertThrows(IllegalArgumentException.class,()->MusicPreferences.rejectedFields(Collections.singletonMap("private\nlabel","v")));}
 @Test public void ignoredDraftConflictCannotBecomePartialBatch(){MusicPreferences.Draft d=new MusicPreferences.Draft(MusicPreferences.snapshot(new MusicPreferences.Values(MusicPreferences.Source.OFFICIAL_WEB,MusicPreferences.Entry.MUSIC_HOME,false,0,null),1));assertNull(d.setEntry(MusicPreferences.Entry.SEARCH));assertNotNull(d.setEntry(MusicPreferences.Entry.LAST_QUEUE));assertThrows(IllegalStateException.class,d::merge);}
 @Test public void newTranslationSetCannotRetainPreviousTranslation(){MusicLyrics.Lyrics original=MusicLyrics.parseLrc("[00:01]original");MusicLyrics.Lyrics first=MusicLyrics.alignTranslations(original,MusicLyrics.parseLrc("[00:01]old translation"));assertEquals("old translation",first.lines().get(0).translation());MusicLyrics.Lyrics second=MusicLyrics.alignTranslations(first,MusicLyrics.parseLrc(""));assertNull(second.lines().get(0).translation());}
 @Test public void missingTranslationNotCalledAmbiguous(){assertTrue(MusicLyrics.alignTranslations(MusicLyrics.parseLrc("[00:01]a"),MusicLyrics.parseLrc("")).ambiguousTranslationTimes().isEmpty());}
 @Test public void duplicateTranslationIsNotSelectedByOrder(){MusicLyrics.Lyrics aligned=MusicLyrics.alignTranslations(MusicLyrics.parseLrc("[00:01]a"),MusicLyrics.parseLrc("[00:01]b\n[00:01]c"));assertNull(aligned.lines().get(0).translation());assertEquals(Collections.singletonList(1000L),aligned.ambiguousTranslationTimes());}
 @Test public void uniqueEarlierWordCanStillBeActiveAfterLaterWordEnds(){MusicLyrics.Lyrics l=MusicLyrics.parse("",MusicLyrics.parseWords("0\t100\ta\n10\t20\tb"));assertEquals(0,l.activeWordAt(30));assertEquals(-1,l.activeWordAt(15));assertEquals(-1,l.activeWordAt(100));}
 @Test public void timingCannotGuessRepeatedWordCharacterOffsets(){MusicLyrics.Lyrics l=MusicLyrics.parse("[00:00]abab",MusicLyrics.parseWords("0\t10\tab\n10\t20\tab"));assertNull(l.activeSpanAt(1));MusicLyrics.Lyrics mapped=l.withNativeSpans(Arrays.asList(new MusicLyrics.WordSpan(0,0,0,2),new MusicLyrics.WordSpan(1,0,2,4)));assertEquals(2,mapped.activeSpanAt(11).start());assertNull(mapped.activeSpanAt(20));}
 @Test public void nativeWordSpanMustMatchExactTextAndUnicodeBoundaries(){MusicLyrics.Lyrics l=MusicLyrics.parse("[00:00]a😀b",MusicLyrics.parseWords("0\t10\t😀"));assertThrows(IllegalArgumentException.class,()->l.withNativeSpans(Collections.singletonList(new MusicLyrics.WordSpan(0,0,1,2))));assertThrows(IllegalArgumentException.class,()->l.withNativeSpans(Collections.singletonList(new MusicLyrics.WordSpan(0,0,0,1))));assertEquals(1,l.withNativeSpans(Collections.singletonList(new MusicLyrics.WordSpan(0,0,1,3))).activeSpanAt(1).start());}
 @Test public void rawBlankLineCountsBoundAllocationBeforeSplitExplosion(){String lines=new String(new char[MusicLyrics.MAX_LINES*2+1]).replace('\0','\n');assertThrows(IllegalArgumentException.class,()->MusicLyrics.parseLrc(lines));String words=new String(new char[MusicLyrics.MAX_WORDS*2+1]).replace('\0','\n');assertThrows(IllegalArgumentException.class,()->MusicLyrics.parseWords(words));}
 @Test public void nullPositionRecordStillRequiresValidCurrentGeometry(){assertThrows(IllegalArgumentException.class,()->LyricPositionStore.restore(null,0,100,160,160));assertThrows(IllegalArgumentException.class,()->LyricPositionStore.restoreExact(null,0,100,160,160));}
 @Test public void exactGeometryDoesNotPermitInvisibleNegativeOrigin(){LyricPositionStore.Record r=new LyricPositionStore.Record(-20,-30,500,500,160,160,1);assertEquals(0,r.horizontalAnchor(),0);assertEquals(0,LyricPositionStore.restoreExact(r,500,500,160,160).x());}
 @Test public void lockedOverlayCannotStartAnOfferedGesture(){LyricOverlayController c=new LyricOverlayController();c.apply(LyricOverlayController.Event.SHOW,0,0);c.apply(LyricOverlayController.Event.LOCK,0,0);assertThrows(IllegalStateException.class,()->c.beginGesture(0,0));}
 @Test public void endedGesturesDoNotExhaustOverlayLifetimeAfter64(){LyricOverlayController c=new LyricOverlayController();c.apply(LyricOverlayController.Event.SHOW,0,0);for(int i=0;i<200;i++){LyricOverlayController.Gesture g=c.beginGesture(0,0);c.endGesture(g,1,1,false);}assertFalse(c.state().dragActive());c.retire();assertThrows(IllegalStateException.class,()->c.beginGesture(0,0));}
 @Test public void readerConsumptionIsNotInventedFromProcessedPrefix()throws Exception{MailSearch.Result r=MailSearch.search(new StringReader("a"+new String(new char[99]).replace('\0','x')),"a",1,()->false);assertEquals(1,r.scannedChars());assertEquals(100,r.readChars());assertEquals(MailSearch.StopReason.RESULT_LIMIT,r.stopReason());}
 @Test public void invalidReaderCountNotEofAndAlwaysCloses(){AtomicBoolean closed=new AtomicBoolean();Reader r=new Reader(){public int read(char[] b,int o,int n){return -2;}public void close(){closed.set(true);}};assertThrows(IOException.class,()->MailSearch.search(r,"a",1,()->false));assertTrue(closed.get());}
 @Test public void cancellationDuringCloseSuppressesPublication(){AtomicBoolean cancelled=new AtomicBoolean();Reader r=new StringReader("match"){@Override public void close(){cancelled.set(true);super.close();}};assertThrows(InterruptedIOException.class,()->MailSearch.search(r,"match",1,cancelled::get));}
 @Test public void noProgressReaderDoesNotSpinForever(){Reader r=new Reader(){int calls;public int read(char[] b,int o,int n){if(++calls>100)fail("unbounded zero-read loop");return 0;}public void close(){}};assertThrows(IOException.class,()->MailSearch.search(r,"a",1,()->false));}
 @Test public void kmpOffsetsEqualNonoverlapReferenceAcrossChunkShapes()throws Exception{Random rnd=new Random(5021);for(int run=0;run<100;run++){StringBuilder b=new StringBuilder();for(int i=0;i<100;i++)b.append(rnd.nextBoolean()?"a":"中");String input=b.toString(),needle=run%2==0?"aa":"中a";List<Long> expected=new ArrayList<>();for(int at=0;;){int next=input.indexOf(needle,at);if(next<0)break;expected.add((long)next);at=next+needle.length();}for(int size:new int[]{1,3,8192}){Reader r=new Reader(){int at;public int read(char[] chars,int o,int n){if(at==input.length())return -1;int count=Math.min(size,Math.min(n,input.length()-at));input.getChars(at,at+count,chars,o);at+=count;return count;}public void close(){}};List<Long> actual=new ArrayList<>();for(MailSearch.Match m:MailSearch.search(r,needle,200,()->false).matches()){actual.add(m.offset());assertTrue(m.snippet().length()<=120);}assertEquals(expected,actual);}}}
}
